function normalizeCheckRuns(raw) {
    if (typeof raw === 'string') {
        try { raw = JSON.parse(raw); } catch (e) {}
    }
    return Array.isArray(raw) ? raw : (raw && raw.check_runs ? raw.check_runs : []);
}

function isPendingStatus(status) { return status === 'in_progress' || status === 'queued' || status === 'pending' || status === 'waiting'; }
function isFailedConclusion(conclusion) { return conclusion === 'failure' || conclusion === 'timed_out' || conclusion === 'action_required'; }

function classifyCheckRuns(checkRuns) {
    var result = { inProgress: false, failed: false, failedNames: [], total: checkRuns.length };
    checkRuns.forEach(function(c) {
        var status = (c.status || '').toLowerCase();
        var conclusion = (c.conclusion || '').toLowerCase();
        if (isPendingStatus(status)) result.inProgress = true;
        if (isFailedConclusion(conclusion)) {
            result.failed = true;
            if (c.name) result.failedNames.push(c.name);
        }
    });
    return result;
}

function checkCiStatus(scm, headSha) {
    var result = { inProgress: false, failed: false, failedNames: [], total: 0 };
