    var allMocks = Object.assign({}, defaults, mocks);

    var scmModule = loadModule(
        'js/common/scm.js',
        makeRequire({ './machineNotice.js': loadModule('js/common/machineNotice.js') }),
        allMocks
    );

    var freshConfigLoader = loadModule(
        'js/configLoader.js',
