        assert.deepEqual(m.normalizeCheckRuns(JSON.stringify([{ name: 'c' }])), [{ name: 'c' }]);
        assert.deepEqual(m.normalizeCheckRuns(JSON.stringify({ check_runs: [{ name: 'd' }] })), [{ name: 'd' }]);
