            { name: 'a', status: 'completed', conclusion: 'success' },
            { name: 'b', status: 'completed', conclusion: 'skipped' },
            { name: 'c', status: 'completed', conclusion: 'neutral' },
            { name: 'd', status: 'completed', conclusion: 'cancelled' },
