 */
function finalizeMergedPR(params, scm, storyKey, prNumber, prUrl, testCaseType, jiraConfig, issueType) {
    console.log('✅ PR #' + prNumber + ' merged successfully');

    try { scm.removeLabel(prNumber, LABELS.PR_APPROVED); } catch (e) {}

